<script setup lang="ts">
import {computed,watch} from 'vue'
import type {PayRule,PayGeneration} from '../payrollTypes'
import {usePayrollText} from '../payrollText'
import {generationMode} from '../payGeneration'
const props=defineProps<{rule:PayRule;disabled?:boolean}>(),{r}=usePayrollText()
const mode=computed({get:()=>generationMode(props.rule),set:(mode:PayGeneration['mode'])=>{props.rule.generation={mode,workingWeekdays:mode==='fixed'?[]:props.rule.generation?.workingWeekdays.length?props.rule.generation.workingWeekdays:[1,2,3,4,5],...(mode==='contract'?{contractTerms:{employmentProration:'',unpaidLeaveTreatment:'',overtimeTreatment:''}}:{})};if(mode==='fixed'){props.rule.basis='monthly';props.rule.overtimeEnabled=false}if(mode==='contract')props.rule.overtimeEnabled=false}})
const needsWeekdays=computed(()=>mode.value==='attendance'&&props.rule.basis==='monthly'||mode.value==='contract'&&!(props.rule.basis==='monthly'&&props.rule.generation?.contractTerms?.employmentProration==='full'&&props.rule.generation?.contractTerms?.unpaidLeaveTreatment==='no_deduction'))
watch(()=>props.rule.generation?.mode,mode=>{if(mode==='contract'&&props.rule.generation&&!props.rule.generation.contractTerms)props.rule.generation.contractTerms={employmentProration:'',unpaidLeaveTreatment:'',overtimeTreatment:''}},{immediate:true})
</script>
<template><fieldset :disabled="disabled"><label>{{r('generationMode')}}<select v-model="mode" :aria-label="r('generationMode')"><option value="manual">{{r('generationManual')}}</option><option value="attendance">{{r('generationAttendance')}}</option><option value="contract">{{r('generationContract')}}</option><option value="fixed">{{r('generationFixed')}}</option></select></label><p class="wf-hint">{{r('recurringHint')}}</p><p v-if="mode==='fixed'" class="wf-hint">{{r('fixedSalaryHint')}}</p><template v-if="mode==='contract'&&rule.generation?.contractTerms"><p class="wf-hint">{{r('contractTermsHint')}}</p><div class="wf-grid"><label>{{r('contractProration')}}<select v-model="rule.generation.contractTerms.employmentProration" required><option value="" disabled>{{r('explicitSelect')}}</option><option value="full">{{r('contractFull')}}</option><option value="working_days">{{r('contractWorkingDays')}}</option></select></label><label>{{r('contractUnpaid')}}<select v-model="rule.generation.contractTerms.unpaidLeaveTreatment" required><option value="" disabled>{{r('explicitSelect')}}</option><option value="no_deduction">{{r('contractNoDeduction')}}</option><option value="deduct">{{r('contractDeduct')}}</option></select></label><label>{{r('contractOvertime')}}<select v-model="rule.generation.contractTerms.overtimeTreatment" required><option value="" disabled>{{r('explicitSelect')}}</option><option value="included">{{r('contractIncluded')}}</option><option value="separate">{{r('contractSeparate')}}</option><option value="not_applicable">{{r('contractNotApplicable')}}</option></select></label></div><p v-if="rule.generation.contractTerms.overtimeTreatment==='separate'" class="wf-hint">{{r('contractSeparateHint')}}</p></template><template v-if="mode==='attendance'||mode==='contract'"><p v-if="mode==='attendance'" class="wf-hint">{{r('attendanceGenerationHint')}}</p><template v-if="needsWeekdays&&rule.generation"><p>{{r('workingWeekdays')}}</p><div class="wf-inline"><label v-for="day in 7" :key="day" class="wf-check"><input v-model="rule.generation.workingWeekdays" type="checkbox" :value="day">{{r('weekday'+day as 'weekday1')}}</label></div></template></template></fieldset></template>
